INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (1, 1, 1, 'Điện thoại iPhone 17', 'iphone-17', NULL, 'iPhone 17', '24990000.00', '27990000.00', 'Điện thoại iPhone 17 mới với chip Apple A19 mạnh mẽ, hệ thống camera kép 48 MP tiên tiến và màn hình ProMotion 120Hz mượt mà.', 'Điện thoại iPhone 17 đánh dấu bước tiến mới với chip Apple A19 6 nhân xử lý vượt trội, màn hình OLED Super Retina XDR ProMotion 120Hz 6.3 inch mang lại trải nghiệm vuốt chạm siêu mượt. Hệ thống camera kép phía sau được nâng cấp toàn diện với camera chính 48 MP và camera góc siêu rộng 48 MP, cùng camera trước 18 MP hỗ trợ FaceTime sắc nét. Máy tích hợp sâu Apple Intelligence, chạy iOS 26, hỗ trợ kết nối 5G siêu tốc và thời lượng pin xem video lên đến 27 giờ.', 'active', 1, 'new', 'public', 12, '["apple","iphone","iphone-17","smartphone","new-release"]', '{"display_specs":"OLED 6.3 inch Super Retina XDR, ProMotion (1-120Hz), Dynamic Island","processor_chipset":"Apple A19 6 nhân","graphics_processor":"Apple GPU 5 nhân","ram_capacity":"8GB","storage_capacity":"128GB, 256GB, 512GB","rear_camera":"Chính 48 MP & Góc siêu rộng 48 MP, Zoom quang học 2x","front_camera":"18 MP TrueDepth","battery_capacity":"27 giờ xem video","charging_speed":"Hỗ trợ sạc nhanh 30W trở lên, Sạc không dây MagSafe 25W","operating_system":"iOS 26","network_connectivity":"5G, Wi-Fi 7, Bluetooth 6.0, NFC","sim_slots":"1 Nano SIM & 1 eSIM (Hỗ trợ 2 eSIM)","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm chuẩn hàng không vũ trụ, Mặt lưng kính pha màu, Mặt trước Ceramic Shield 2","dimensions_weight":"149.6 × 71.5 × 7.95 mm, 177g","release_year":"2025","other_features":"Kháng nước/bụi IP68, Face ID, Apple Intelligence"}', '[{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Đen","Trắng","Tím Oải Hương","Xanh Lá Xô Thơm","Xanh Lam Khói"]}]', 0, 0, '4.50', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (2, 1, 1, 'Điện thoại iPhone 17e', 'iphone-17e', NULL, 'iPhone 17e', '17990000.00', '19990000.00', 'Điện thoại iPhone 17e với chip Apple A19, camera 48 MP, màn hình OLED 6.1 inch Super Retina XDR.', 'Điện thoại iPhone 17e được trang bị chip Apple A19 6 nhân, màn hình OLED 6.1 inch Super Retina XDR, camera sau 48 MP, camera trước 12 MP, hỗ trợ 5G, iOS 26 và pin xem video lên đến 26 giờ.', 'active', 1, 'new', 'public', 12, '["apple","iphone","iphone-17e","smartphone"]', '{"display_specs":"OLED 6.1 inch Super Retina XDR","processor_chipset":"Apple A19 6 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"8GB","storage_capacity":"256GB, 512GB","rear_camera":"48 MP","front_camera":"12 MP","battery_capacity":"26 giờ","charging_speed":"20 W","operating_system":"iOS 26","network_connectivity":"5G","sim_slots":"1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm, mặt lưng kính","dimensions_weight":"146.7 × 71.5 × 7.8 mm, 170g","release_year":"2026","other_features":"Apple Intelligence, Face ID, Kháng nước/bụi IP68"}', '[{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Hồng nhạt","Đen","Trắng"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (3, 1, 1, 'Điện thoại iPhone 17 Pro', 'iphone-17-pro', NULL, 'iPhone 17 Pro', '28490000.00', '30990000.00', 'Điện thoại iPhone 17 Pro với chip A19 Pro mạnh mẽ, màn hình ProMotion 3000 nits và hệ thống camera Pro Fusion 48MP.', 'Điện thoại iPhone 17 Pro định nghĩa lại đẳng cấp với khung nhôm nguyên khối Unibody, chip Apple A19 Pro (3nm) tối ưu nhiệt độ bằng buồng hơi (Vapor Chamber). Màn hình 6.3 inch sáng kỷ lục 3000 nits phủ Ceramic Shield 2. Hệ thống camera sau 3 ống kính 48MP hỗ trợ zoom quang học tới 8x và camera trước 18MP Center Stage.', 'active', 1, 'new', 'public', 12, '["apple","iphone","iphone-17-pro","smartphone","ios26"]', '{"display_specs":"6.3 inch, OLED Super Retina XDR, 120Hz ProMotion, 3000 nits","processor_chipset":"Apple A19 Pro 6 nhân (Tiến trình 3nm), GPU 6 nhân","graphics_processor":"Apple GPU 6 nhân","ram_capacity":"12GB","storage_capacity":"256GB, 512GB, 1TB","rear_camera":"3x48MP (Chính, Góc siêu rộng, Tele zoom 8x)","front_camera":"18MP Center Stage","battery_capacity":"Xem video lên đến 31 giờ","charging_speed":"Sạc nhanh 40W, sạc không dây MagSafe","operating_system":"iOS 26","network_connectivity":"Wi-Fi 7, 5G (10Gb/s), Bluetooth 6.0","sim_slots":"1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm nguyên khối, mặt lưng kính Ceramic Shield","dimensions_weight":"150.0 × 71.9 × 8.75 mm, 206g","release_year":"2025","other_features":"Apple Intelligence, Face ID, Kháng nước/bụi IP68, Camera Control"}', '[{"name":"storage","values":["256GB","512GB","1TB"]},{"name":"color","values":["Bạc","Cam Vũ Trụ","Xanh Đậm"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (4, 1, 1, 'Điện thoại iPhone 17 Pro Max', 'iphone-17-pro-max', NULL, 'iPhone 17 Pro Max', '37990000.00', '39990000.00', 'Điện thoại iPhone 17 Pro Max sở hữu màn hình 6.9 inch lớn nhất từ trước đến nay, bộ 3 camera 48 MP đỉnh cao và chip Apple A19 Pro siêu mạnh mẽ.', 'Điện thoại iPhone 17 Pro Max là phiên bản cao cấp nhất của Apple, nổi bật với màn hình OLED 6.9 inch Super Retina XDR ProMotion 120Hz siêu lớn và độ sáng tối đa lên tới 3000 nits. Máy trang bị chip Apple A19 Pro mang lại hiệu năng dẫn đầu, hệ thống 3 camera sau 48 MP hỗ trợ chụp ảnh chuẩn studio và quay video 4K chuyên nghiệp. Pin cực khủng cho thời lượng xem video lên đến 37 giờ, tích hợp sâu Apple Intelligence, chạy iOS 26 và sạc nhanh công suất 40W.', 'active', 1, 'new', 'public', 12, '["apple","iphone","iphone-17-pro-max","smartphone","flagship"]', '{"display_specs":"OLED 6.9 inch Super Retina XDR (1320 x 2868 Pixels), ProMotion (1-120Hz)","processor_chipset":"Apple A19 Pro","graphics_processor":"Apple GPU","ram_capacity":"12GB","storage_capacity":"256GB, 512GB, 1TB, 2TB","rear_camera":"Bộ 3 camera 48 MP, Zoom quang học","front_camera":"18 MP TrueDepth","battery_capacity":"37 giờ xem video","charging_speed":"Sạc nhanh 40W, Sạc không dây MagSafe","operating_system":"iOS 26","network_connectivity":"5G, Wi-Fi 7, Bluetooth 6.0, NFC","sim_slots":"1 Nano SIM & 1 eSIM (Hỗ trợ 2 eSIM)","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm nguyên khối & Mặt lưng kính cường lực","dimensions_weight":"163.4 × 78 × 8.75 mm, 233g","release_year":"2025","other_features":"Kháng nước/bụi IP68, Face ID, Nút Điều khiển Camera (Camera Control), Apple Intelligence"}', '[{"name":"storage","values":["256GB","512GB","1TB","2TB"]},{"name":"color","values":["Bạc","Xanh đậm","Cam Vũ Trụ"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (5, 1, 2, 'Điện thoại Samsung Galaxy A57', 'samsung-galaxy-a57', NULL, 'Samsung Galaxy A57', '12490000.00', '12990000.00', 'Điện thoại Samsung Galaxy A57 nổi bật với chip Exynos 1680 8 nhân mạnh mẽ, màn hình Super AMOLED Plus 120Hz mượt mà và bộ 3 camera 50 MP chống rung quang học OIS.', 'Điện thoại Samsung Galaxy A57 mang đến trải nghiệm thị giác tuyệt đỉnh với màn hình 6.7 inch Super AMOLED Plus, độ phân giải Full HD+ cùng tần số quét 120Hz và độ sáng lên tới 1900 nits. Máy sở hữu cấu hình mạnh mẽ nhờ vi xử lý Exynos 1680 và GPU Xclipse 550, đáp ứng mượt mà mọi nhu cầu từ làm việc đến chơi game đồ họa cao. Hệ thống camera vượt trội với camera chính 50 MP hỗ trợ OIS, quay video 4K sắc nét. Cùng viên pin 5000 mAh, sạc siêu nhanh 45W, khung kim loại sang trọng và chuẩn kháng nước IP68, đây là chiếc điện thoại toàn diện trong phân khúc.', 'active', 1, 'new', 'public', 12, '["samsung","galaxy-a","samsung-galaxy-a57","smartphone","android","new-release"]', '{"display_specs":"Super AMOLED Plus 6.7 inch Full HD+ (1080 x 2340 Pixels), 120Hz","processor_chipset":"Exynos 1680 8 nhân","graphics_processor":"Xclipse 550","ram_capacity":"8GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Phụ 12 MP, 5 MP, Chống rung quang học (OIS)","front_camera":"12 MP","battery_capacity":"5000 mAh","charging_speed":"Sạc siêu nhanh 45W (Super Fast Charging 2.0)","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 6E, Bluetooth 6.0, NFC","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung kim loại & Mặt lưng kính cường lực Gorilla Glass Victus+","dimensions_weight":"161.5 × 76.8 × 6.9 mm, 182g","release_year":"2026","other_features":"Kháng nước/bụi IP68, Mở khoá vân tay dưới màn hình, Mở khoá khuôn mặt"}', '[{"name":"storage","values":["128GB (8GB RAM)","256GB (8GB RAM)","256GB (12GB RAM)"]},{"name":"color","values":["Tím ngọc","Xám khói","Xanh đêm (Navy)","Xanh băng"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (6, 1, 2, 'Điện thoại Samsung Galaxy A37', 'samsung-galaxy-a37', NULL, 'Samsung Galaxy A37', '10290000.00', NULL, 'Điện thoại Samsung Galaxy A37 nổi bật với chip Exynos 1480 8 nhân mạnh mẽ, màn hình Super AMOLED 120Hz mượt mà và bộ 3 camera 50 MP hỗ trợ chống rung quang học OIS.', 'Điện thoại Samsung Galaxy A37 mang đến trải nghiệm thị giác ấn tượng với màn hình 6.7 inch Super AMOLED, độ phân giải Full HD+ cùng tần số quét 120Hz và độ sáng tối đa 1900 nits. Máy sở hữu cấu hình ổn định nhờ vi xử lý Exynos 1480 và GPU Xclipse 530, đáp ứng mượt mà các nhu cầu làm việc và giải trí hàng ngày. Hệ thống camera chụp ảnh sắc nét với cảm biến chính 50 MP hỗ trợ OIS, quay video 4K chất lượng cao. Cùng viên pin lớn 5000 mAh, sạc siêu nhanh 45W, và chuẩn kháng nước, bụi IP68, đây là chiếc điện thoại toàn diện trong phân khúc tầm trung.', 'active', 1, 'new', 'public', 12, '["samsung","galaxy-a","samsung-galaxy-a37","smartphone","android","new-release"]', '{"display_specs":"Super AMOLED 6.7 inch Full HD+ (1080 x 2340 Pixels), 120Hz, 1900 nits","processor_chipset":"Exynos 1480 8 nhân","graphics_processor":"Xclipse 530","ram_capacity":"6GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Phụ 8 MP, 5 MP, Chống rung quang học (OIS)","front_camera":"12 MP","battery_capacity":"5000 mAh","charging_speed":"Sạc siêu nhanh 45W (Super Fast Charging 2.0)","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 6 Dual-band, Bluetooth v5.3, NFC","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhựa & Mặt lưng kính cường lực Gorilla Glass Victus+","dimensions_weight":"162.9 × 78.2 × 7.4 mm, 196g","release_year":"2026","other_features":"Kháng nước/bụi IP68, Mở khoá vân tay dưới màn hình, Mở khoá khuôn mặt"}', '[{"name":"storage","values":["128GB (6GB RAM)","128GB (8GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Trắng","Đen","Xanh lá đậm","Tím"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (7, 1, 3, 'Điện thoại Xiaomi Redmi Note 15 5G', 'xiaomi-redmi-note-15-5g', NULL, 'Xiaomi Redmi Note 15 5G', '7490000.00', NULL, 'Điện thoại Xiaomi Redmi Note 15 5G sở hữu thiết kế siêu mỏng 7.35mm, màn hình AMOLED cong 120Hz mượt mà, chip Snapdragon 6 Gen 3 và camera 108 MP hỗ trợ chống rung OIS.', 'Điện thoại Xiaomi Redmi Note 15 5G mang đến thiết kế thanh thoát với độ mỏng ấn tượng chỉ 7.35 mm và chuẩn kháng nước, bụi IP66. Máy sở hữu màn hình cong AMOLED 6.77 inch, độ phân giải Full HD+, tần số quét 120Hz và độ sáng tối đa lên đến 3200 nits, cho khả năng hiển thị ngoài trời xuất sắc. Sức mạnh bên trong đến từ vi xử lý Snapdragon 6 Gen 3 cùng hệ điều hành HyperOS 2 mới nhất, đảm bảo hiệu năng đa nhiệm mượt mà. Điểm nhấn nổi bật là hệ thống camera 108 MP "108 MasterPixel Edition" tích hợp OIS, hỗ trợ quay video 4K sắc nét.', 'active', 1, 'new', 'public', 18, '["xiaomi","redmi","redmi-note-15","smartphone","android","5g"]', '{"display_specs":"AMOLED cong 6.77 inch Full HD+, 120Hz, 3200 nits","processor_chipset":"Snapdragon 6 Gen 3 8 nhân (4 nhân 2.4 GHz & 4 nhân 1.8 GHz)","graphics_processor":"Adreno 710","ram_capacity":"6GB","storage_capacity":"128GB, 256GB (Hỗ trợ thẻ nhớ MicroSD)","rear_camera":"108 MP \'108 MasterPixel Edition\', Chống rung quang học (OIS)","front_camera":"20 MP","battery_capacity":"5520 mAh","charging_speed":"Sạc nhanh 45W","operating_system":"Xiaomi HyperOS 2","network_connectivity":"5G, Wi-Fi, Bluetooth","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 MicroSD","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung viền & mặt lưng nhựa Polycarbonate cao cấp","dimensions_weight":"164 x 75.4 x 7.4 mm, 178g","release_year":"2025","other_features":"Kháng nước/bụi IP66, Mở khoá vân tay dưới màn hình, Nhận diện khuôn mặt"}', '[{"name":"storage","values":["128GB (6GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Xanh Dương","Đen","Tím"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (8, 1, 3, 'Điện thoại Xiaomi Redmi Note 15 Pro 5G', 'xiaomi-redmi-note-15-pro-5g', NULL, 'Xiaomi Redmi Note 15 Pro 5G', '10190000.00', NULL, 'Điện thoại Xiaomi Redmi Note 15 Pro 5G nổi bật với camera 200MP siêu nét, viên pin khủng 6580 mAh công nghệ Silicon-Carbon và chuẩn siêu bền chống rơi 2.5m.', 'Điện thoại Xiaomi Redmi Note 15 Pro 5G mang đến trải nghiệm toàn diện với màn hình AMOLED 6.83 inch độ phân giải 1.5K, tần số quét 120Hz và độ sáng tối đa lên tới 3200 nits. Máy sở hữu hiệu năng mạnh mẽ nhờ vi xử lý MediaTek Dimensity 7400-Ultra và hệ điều hành HyperOS 2.2. Điểm nhấn của sản phẩm là hệ thống camera chính lên đến 200 MP cho độ chi tiết ấn tượng, cùng viên pin "khổng lồ"6580 mAh công nghệ Silicon-Carbon hỗ trợ sạc nhanh 45W. Đặc biệt, máy cực kỳ bền bỉ với kính cường lực Gorilla Glass Victus 2, chuẩn chống nước/bụi IP68, IP69, IP69K và khả năng chống rơi vỡ từ độ cao 2.5m (chứng nhận SGS).', 'active', 1, 'new', 'public', 18, '["xiaomi","redmi","redmi-note-15-pro","smartphone","android","5g"]', '{"display_specs":"AMOLED 6.83 inch 1.5K (1280 x 2772 Pixels), 120Hz, 3200 nits","processor_chipset":"MediaTek Dimensity 7400-Ultra 8 nhân","graphics_processor":"Mali-G615","ram_capacity":"8GB","storage_capacity":"256GB, 512GB","rear_camera":"Chính 200 MP & Phụ 8 MP","front_camera":"20 MP (Hỗ trợ Xóa phông, Làm đẹp AI)","battery_capacity":"6580 mAh (Pin Silicon-Carbon)","charging_speed":"Sạc nhanh TurboCharge 45W, Sạc ngược qua cáp","operating_system":"Xiaomi HyperOS 2.2","network_connectivity":"5G, Wi-Fi 6E, Bluetooth v5.4, NFC, Hồng ngoại","sim_slots":"2 Nano SIM hoặc 1 Nano SIM + 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung viền & mặt lưng nhựa Polycarbonate cao cấp, Kính cường lực Corning Gorilla Glass Victus 2","dimensions_weight":"163.6 × 78.1 × 7.96 mm, 210g","release_year":"2025","other_features":"Kháng nước/bụi (IP66, IP68, IP69, IP69K), Chống rơi vỡ 2.5m, Mở khoá vân tay dưới màn hình, Nhận diện khuôn mặt"}', '[{"name":"storage","values":["256GB (8GB RAM)","256GB (12GB RAM)","512GB (12GB RAM)"]},{"name":"color","values":["Tím","Titan xám","Đen"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:00:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (9, 1, 4, 'Điện thoại Oppo Find X8 Pro', 'oppo-find-x8-pro', NULL, 'Oppo Find X8 Pro', '29990000.00', '32990000.00', 'Điện thoại Siêu phẩm Flagship Oppo Find X8 Pro với Camera Hasselblad, chip Dimensity 9400 mạnh mẽ mượt mà.', 'Điện thoại Oppo Find X8 Pro mang thiết kế sang trọng với cụm camera sau hợp tác cùng Hasselblad. Máy trang bị vi xử lý cao cấp MediaTek Dimensity 9400, màn hình AMOLED 120Hz LTPO đỉnh cao.', 'active', 1, 'new', 'public', 12, '["oppo","find-x8","flagship"]', '{"display_specs":"AMOLED 6.78 inch 1.5K, 120Hz","processor_chipset":"Dimensity 9400 8 nhân","graphics_processor":"Immortalis-G925","ram_capacity":"12GB, 16GB","storage_capacity":"256GB, 512GB, 1TB","rear_camera":"50MP (Chính) + 50MP (Ultrawide) + 50MP (Tele) + 50MP (Periscope)","front_camera":"32 MP","battery_capacity":"5910 mAh","charging_speed":"Sạc nhanh 80W, không dây 50W","operating_system":"Android 15, ColorOS 15","network_connectivity":"5G, Wi-Fi 7, Bluetooth 5.4, NFC","sim_slots":"2 Nano SIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung hợp kim, mặt lưng kính","dimensions_weight":"162.27 mm x 76.6 mm x 8.24 mm, 215g","release_year":"2024","other_features":"Kháng nước IP68/IP69, Các tính năng AI"}', '[{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Trắng","Đen"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 02:33:56', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (10, 1, 4, 'Điện thoại OPPO Reno15 5G', 'oppo-reno15-5g', NULL, 'OPPO Reno15 5G', '15690000.00', '15990000.00', 'Điện thoại Thiết kế Aurora Vitality cuốn hút, Camera 50MP đỉnh cao chân dung và chuẩn kháng nước IP69.', 'Điện thoại OPPO Reno 15 5G là mẫu smartphone kết hợp hài hòa giữa thiết kế thẩm mỹ và công nghệ hiện đại. Máy nổi bật với khả năng chụp ảnh chân dung chất lượng cao cùng hiệu năng mạnh mẽ từ phần cứng mới. Bên cạnh đó, máy chú trọng độ bền với thiết kế Aurora Vitality và chuẩn kháng nước IP69 ấn tượng, phù hợp cho người dùng tìm kiếm thiết bị toàn diện.', 'active', 0, 'new', 'public', 12, '["oppo","reno15","smartphone","5g"]', '{"display_specs":"AMOLED, 1.5K (1256 x 2760 Pixels), 6.59\\" - 120 Hz, 1200 nits, Gorilla Glass 7i","processor_chipset":"Snapdragon 7 Gen 4 8 nhân 2.8 GHz","graphics_processor":"Adreno 722","ram_capacity":"8GB / 12GB","storage_capacity":"256GB","rear_camera":"Chính 50 MP & Phụ 50 MP, 8 MP, Quay 4K@60fps","front_camera":"50 MP","battery_capacity":"6500 mAh, Li-Po, SuperVOOC","charging_speed":"80 W","operating_system":"ColorOS 16 (Android 16)","network_connectivity":"5G, Wi-Fi 6, Dual-band, Bluetooth v5.4, GPS, NFC, Hồng ngoại","sim_slots":"2 Nano SIM hoặc 1 Nano SIM + 1 eSIM","charging_port":"Type-C","audio_jack":"Không có","build_material":"Khung hợp kim nhôm, Mặt lưng kính","dimensions_weight":"Dài 158 mm - Ngang 74.83 mm - Dày 7.89 mm/7.77 mm - Nặng 197 g","release_year":"01/2026","other_features":"Vân tay dưới màn hình, Kháng nước IP69, IP68, IP66"}', '[{"name":"storage","values":["256GB"]},{"name":"ram","values":["8GB","12GB"]},{"name":"color","values":["Xanh Dương","Trắng"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-25 00:41:39', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (11, 1, 5, 'Điện thoại realme C85', 'realme-c85', NULL, 'realme C85', '5490000.00', '5690000.00', 'Điện thoại realme C85 nổi bật với pin siêu khủng 7000 mAh, sạc nhanh 45W cùng màn hình siêu lớn 6.8 inch 144Hz thao tác mượt mà.', 'Điện thoại realme C85 mang hình hài vạm vỡ kết hợp cùng không gian giải trí đỉnh cao nhờ màn hình siêu lớn 6.8 inch IPS LCD cùng tần số quét 144Hz. Điểm ấn tượng nhất là viên pin dung lượng khổng lồ 7000 mAh cho thời lượng sử dụng vượt trội nhiều ngày, đi kèm công nghệ sạc cực nhanh 45W. Về hiệu năng, máy trang bị vi xử lý Snapdragon 685 đa nhiệm mượt mà cùng camera chính 50 MP, kháng nước bụi toàn diện tới IP69K, đáp ứng xuất sắc mọi chu cầu trong phân khúc giá phổ thông.', 'active', 0, 'new', 'public', 12, '["realme","c85","smartphone","4g"]', '{"display_specs":"IPS LCD 6.8 inch HD+ (720 x 1570 Pixels), 144Hz, 1200 nits","processor_chipset":"Snapdragon 685 8 nhân (2 nhân 2.4 GHz & 6 nhân 2 GHz)","graphics_processor":"Adreno 610","ram_capacity":"6GB, 8GB","storage_capacity":"128GB","rear_camera":"Chính 50 MP & Cảm biến Flicker","front_camera":"8 MP","battery_capacity":"7000 mAh, Li-Ion","charging_speed":"45 W","operating_system":"Android 15","network_connectivity":"4G, Wi-Fi 5 (Dual-band), Bluetooth v5.3, GPS","sim_slots":"2 Nano SIM hoặc 1 Nano SIM + 1 thẻ nhớ (MicroSD)","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Khung & Mặt lưng nhựa","dimensions_weight":"Dài 166.18 mm - Ngang 78.03 mm - Dày 8.38 mm - Nặng 212 g","release_year":"2026","other_features":"Kháng nước/bụi IP66/IP68/IP69K, Vân tay cạnh viền, Không gian trẻ em"}', '[{"name":"storage","values":["128GB (6GB RAM)","128GB (8GB RAM)"]},{"name":"color","values":["Xanh dương nhạt","Đen"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 02:15:56', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (12, 1, 5, 'Điện thoại realme C85 Pro', 'realme-c85-pro', NULL, 'realme C85 Pro', '6590000.00', '6990000.00', 'Điện thoại realme C85 Pro nổi bật với Snapdragon 685, pin khủng 7000 mAh sạc nhanh 45W, màn hình AMOLED 6.8 inch 120Hz siêu sáng 4000 nits, camera chính 50MP, kháng nước, bụi chuẩn IP69 Pro, độ bền chuẩn quân đội MIL-STD 810H.', 'Điện thoại realme C85 Pro là mẫu smartphone bền bỉ đậm chất gaming và giải trí. Máy sở hữu màn hình AMOLED 6.8 inch đạt độ sáng tối đa 4000 nits, tần số quét 120Hz mượt mà cùng kính cường lực AGC DT-Star2. Điểm nhấn là cấu hình Snapdragon 685 kết hợp viên pin cực lớn 7000 mAh hỗ trợ sạc nhanh 45W, tản nhiệt Bionic VC đảm bảo hiệu suất xử lý lâu dài. Về độ bền, máy đạt chuẩn chuẩn quân đội MIL-STD 810H, kháng nước bụi IP69 Pro cùng nhiều tính năng AI đột phá.', 'active', 1, 'new', 'public', 12, '["realme","c85 pro","smartphone","amoled","7000mah"]', '{"display_specs":"AMOLED 6.8 inch Full HD+ (1080 x 2344 Pixels), 120Hz, 4000 nits, Kính cường lực AGC DT-Star2","processor_chipset":"Snapdragon 685 8 nhân (4 nhân 2.8 GHz & 4 nhân 1.9 GHz)","graphics_processor":"Adreno 610","ram_capacity":"8GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Cảm biến Flicker, Xoá phông, Tilt-shift, Night Mode","front_camera":"8 MP, Xóa phông, HDR, Chụp đêm","battery_capacity":"7000 mAh, Li-Ion","charging_speed":"45 W, Sạc siêu nhanh SuperVOOC, Sạc ngược qua cáp","operating_system":"Android 15","network_connectivity":"4G, Wi-Fi 5 (Dual-band), Bluetooth v5.0, NFC, GPS","sim_slots":"2 Nano SIM, hỗ trợ thẻ nhớ MicroSD","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Khung & Mặt lưng nhựa","dimensions_weight":"Dài 164.4 mm - Ngang 77.99 mm - Dày 8.09 mm - Nặng 205 g","release_year":"2025","other_features":"Kháng nước/bụi IP69 Pro, Độ bền MIL-STD 810H, Mở khoá vân tay dưới màn hình, Tản nhiệt Bionic VC, Các năng AI (Gemini, AI Edit)"}', '[{"name":"storage","values":["128GB (8GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Tím","Xanh lá"]}]', 0, 0, '0.00', '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 02:35:08', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (13, 2, 1, 'Máy tính bảng iPad A16 WiFi', 'ipad-a16-wifi', NULL, 'iPad A16 WiFi', '9690000.00', '9790000.00', 'Máy tính bảng iPad A16 WiFi với thiết kế siêu mỏng, hiệu năng mạnh mẽ từ chip Apple A16, màn hình Retina IPS LCD 11 inch sắc nét.', 'Máy tính bảng iPad A16 mang đến trải nghiệm tuyệt vời với màn hình Retina IPS LCD 11 inch, chip Apple A16 5 nhân mạnh mẽ xử lý mọi tác vụ từ làm việc đến giải trí. Camera trước và sau đều là 12MP hỗ trợ chụp hình và quay video 4K sắc nét, cùng kết nối mạng Wi-Fi 6 tốc độ cao. Tính năng đặc biệt tích hợp âm thanh Dolby Atmos, ghi âm, quay chụp chuyên nghiệp đem lại cảm giác tối ưu cho người dùng.', 'active', 1, 'new', 'public', 12, '["ipad","máy tính bảng","apple","a16","tablet"]', '{"display_specs":"Retina IPS LCD, 11\\", 1640 x 2360 Pixels, Tần số quét 60 Hz","processor_chipset":"Apple A16 5 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"6GB","storage_capacity":"128GB, 256GB (Khả dụng khoảng 113GB / 241GB)","rear_camera":"12 MP (Hỗ trợ Smart HDR 4, quay 4K 2160p@60fps, Chế độ điện ảnh, Quay chậm)","front_camera":"12 MP (Góc siêu rộng, Flash Retina, Quay video Full HD, Chế độ điện ảnh)","battery_capacity":"28.93 Wh, Li-Po","charging_speed":"Tối đa 20 W","operating_system":"iPadOS 18","network_connectivity":"Wi-Fi 6, MIMO, Dual-band, Bluetooth v5.3, GPS, iBeacon, Nghe gọi qua FaceTime","sim_slots":"Không","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 248.6 mm - Ngang 179.5 mm - Dày 7 mm - Nặng 477 g","release_year":"03/2025","other_features":"Âm thanh Dolby Atmos, Trung tâm màn hình, Mở khóa vân tay Touch ID, Hỗ trợ bàn phím rời, Hỗ trợ Apple Pencil 1, Micro kép, Có ghi âm"}', '[{"name":"storage","values":["128GB","256GB"]},{"name":"color","values":["Xanh Dương","Bạc","Hồng","Vàng"]}]', 0, 0, '0.00', '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 04:47:06', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (14, 2, 1, 'Máy tính bảng iPad A16 5G', 'ipad-a16-5g', NULL, 'iPad A16 5G', '13990000.00', NULL, 'Máy tính bảng iPad A16 5G hỗ trợ tốc độ mạng 5G siêu nhanh, thiết kế cá tính cùng chip Apple A16 mạnh mẽ.', 'Máy tính bảng iPad A16 5G tiếp nối thành công với khả năng kết nối mạng di động 5G cực nhanh, đáp ứng nhu cầu làm việc và giải trí linh hoạt ở mọi nơi. Máy sở hữu màn hình Retina IPS LCD 11 inch sắc nét, vi xử lý Apple A16 5 nhân mạnh mẽ. Cụm camera trước, sau 12MP mang đến chất lượng chụp ảnh và gọi FaceTime chất lượng cao.', 'active', 1, 'new', 'public', 12, '["ipad","máy tính bảng","apple","a16","5g","tablet"]', '{"display_specs":"Retina IPS LCD, 11\\", 1640 x 2360 Pixels, Tần số quét 60 Hz","processor_chipset":"Apple A16 5 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"6GB","storage_capacity":"128GB, 256GB, 512GB (Khả dụng khoảng 113GB / 241GB / 497GB)","rear_camera":"12 MP (Hỗ trợ Smart HDR 4, quay 4K 2160p@60fps, Chế độ điện ảnh, Quay chậm)","front_camera":"12 MP (Góc siêu rộng, Flash Retina, Quay video Full HD, Chế độ điện ảnh)","battery_capacity":"28.93 Wh, Li-Po","charging_speed":"Tối đa 20 W","operating_system":"iPadOS 18","network_connectivity":"5G, Wi-Fi 6, MIMO, Dual-band, Bluetooth v5.3, GPS, iBeacon, Nghe gọi qua FaceTime","sim_slots":"1 eSIM","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 248.6 mm - Ngang 179.5 mm - Dày 7 mm - Nặng 481 g","release_year":"03/2025","other_features":"Âm thanh Dolby Atmos, Trung tâm màn hình, Mở khóa bằng vân tay Touch ID, Kết nối bàn phím rời, Kết nối Apple Pencil 1, Micro kép, Có ghi âm"}', '[{"name":"storage","values":["128GB","256GB","512GB"]},{"name":"color","values":["Bạc","Vàng","Xanh Dương","Hồng"]}]', 1600, 12000, '0.00', '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 09:46:46', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (15, 2, 2, 'Máy tính bảng Samsung Galaxy Tab S11 WiFi', 'samsung-galaxy-tab-s11-wifi', NULL, 'Samsung Galaxy Tab S11 WiFi', '20990000.00', NULL, 'Máy tính bảng Samsung Galaxy Tab S11 WiFi trang bị màn hình 11" 120Hz mượt mà, bút S Pen đa năng cùng hệ sinh thái Galaxy AI thông minh.', 'Máy tính bảng Samsung Galaxy Tab S11 WiFi đem đến trải nghiệm làm việc và giải trí đỉnh cao nhờ thiết kế nhôm nguyên khối, kháng nước đỉnh cao IP68. Ghi dấu với chip MediaTek Dimensity 9400+, dung lượng RAM 12GB mạnh mẽ cùng loạt trợ lý AI (Khoanh tròn tìm kiếm, Note quyền năng, Google Gemini). Hệ thống camera xóa phông AI và âm thanh vòm Dolby Atmos tinh chỉnh bởi AKG sẽ nâng tầm mọi trải nghiệm.', 'active', 1, 'new', 'public', 12, '["samsung","galaxy","tab s11","wifi","máy tính bảng","tablet","ai"]', '{"display_specs":"Dynamic AMOLED 2X, 11\\", 1600 x 2560 Pixels, Tần số quét 120 Hz","processor_chipset":"MediaTek Dimensity 9400+ 8 nhân","graphics_processor":"ARM Immortalis-G925","ram_capacity":"12GB","storage_capacity":"128GB, 256GB","rear_camera":"13 MP (Quay phim 4K 2160p@30fps, Xóa phông, Bộ lọc màu)","front_camera":"12 MP (Xóa phông, Làm đẹp, Bộ lọc màu)","battery_capacity":"8400 mAh, Li-Ion","charging_speed":"Tối đa 45 W","operating_system":"Android 16","network_connectivity":"Wi-Fi 6, Wi-Fi Direct, Dual-band, 6 GHz, Bluetooth v5.4, GPS","sim_slots":"Không","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 165.3 mm - Ngang 253.8 mm - Dày 5.5 mm - Nặng 469 g","release_year":"09/2025","other_features":"Trợ lý AI (Google Gemini, Dịch trực tiếp, Note, Ghi âm), Khoanh tròn tìm kiếm, Xoá vật thể AI, Âm thanh AKG & Dolby Atmos, Samsung DeX, Kết nối bút S Pen, Vân tay dưới MH, IP68"}', '[{"name":"storage","values":["128GB","256GB"]},{"name":"color","values":["Xám","Bạc"]}]', 236, 2000, '0.00', '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 10:03:35', '2026-05-02 06:24:11', NULL, NULL, NULL);
