rage","values":["512GB","1TB"]},{"name":"color","values":["Đen","Bạc"]},{"name":"ram","values":["16GB","24GB"]}]', 340, 10000, '0.00', '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 09:36:53', '2026-05-02 06:24:11', NULL, NULL, NULL);
