 '[{"name":"ram","values":["16GB","24GB"]},{"name":"storage","values":["512GB","256GB"]},{"name":"color","values":["Xanh đen","Bạc","Vàng","Xanh da trời nhạt"]}]', 0, 0, '0.00', '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 10:43:14', '2026-05-02 06:24:11', NULL, NULL, NULL);
INSERT INTO products (`id`, `category_id`, `brand_id`, `name`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description`, `description`, `status`, `is_featured`, `condition`, `visibility`, `warranty_months`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `shipping_info`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`, `brand`, `sku`) VALUES (26, 3, 1, 'Laptop MacBook Air 15 inch M4', 'macbook-air-15-inch-m4', NULL, 'MacBook Air 15 inch M4', '31390000.00', NULL, 'Laptop MacBook Air 15 inch M4 mới với chip Apple M4 mạnh mẽ, màn hình Liquid Retina 15.3 inch tuyệt đẹp và thiết kế siêu mỏng nhẹ.', 'Laptop MacBook Air 15 inch M4 mang trong mình sức mạnh vượt trội từ chip Apple M4 10 nhân CPU và 10 nhân GPU, cùng bộ nhớ RAM 16GB mặc định giúp xử lý mượt mà mọi tác vụ. Màn hình Liquid Retina 15.3 inch với độ sáng 500 nits, công nghệ True Tone và dải màu rộng (P3) cho trải nghiệm hình ảnh sống động. Máy sở hữu thiết kế vỏ nhôm tái chế 100% siêu mỏng nhẹ chỉ 11.5mm và nặng 1.51kg, thời lượng pin ấn tượng cùng macOS Sequoia mới nhất.', 'active', 1, 'new', 'public', 12, '["macbook","apple","macbook air","macbook m4","laptop cao cấp"]', '{"cpu":"Apple M4 10 nhân (120 GB/s memory bandwidth)","ram":"16 GB (Không hỗ trợ nâng cấp)","hard_drive":"SSD","screen":"15.3\\" Liquid Retina, IPS, Wide color (P3), 500 nits, True Tone, 1 tỷ màu","graphics":"Card tích hợp - 10 nhân GPU","audio":"Hệ thống âm thanh 6 loa, 3 microphones, Dolby Atmos","ports":"MagSafe 3, 2 x Thunderbolt 4.0 (hỗ trợ USB 4, USB Type-C, DisplayPort và Power Delivery)","audio_jack":"3.5 mm","connectivity":"Wi-Fi 6E (802.11ax), Bluetooth 5.3","card_reader":"Không","webcam":"1080p FaceTime HD camera","operating_system":"macOS Sequoia","keyboard_backlight":"Đơn sắc - Màu trắng","security":"Bảo mật vân tay","cooling_system":"Không quạt tản nhiệt","special_features":"Vỏ nhôm tái chế 100%","battery":"Li-Po, 66.5 Wh","dimensions_weight":"Dài 340.4 mm - Rộng 237.6 mm - Dày 11.5 mm - 1.51 kg","build_material":"Nhôm nguyên khối","release_year":"2025"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Xanh đen","Bạc","Vàng","Xanh da trời nhạt"]}]', 0, 0, '0.00', '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-28 00:06:00', '2026-05-02 06:24:11', NULL, NULL, NULL);
