perating_system":"Windows 11 Home SL","keyboard_backlight":"Không có đèn","security":"Công tắc khoá camera, Bảo mật vân tay","cooling_system":"Hãng không công bố","special_features":"Độ bền chuẩn quân đội MIL STD 810H, Bản lề mở 180 độ","battery":"3-cell Li-ion, 42 Wh","dimensions_weight":"Dài 360.3 mm - Rộng 232.5 mm - Dày 17.9 mm - 1.63 kg","build_material":"Vỏ nhựa","release_year":"2023"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["512GB"]},{"name":"color","values":["Bạc"]}]', 0, 0, '0.00', '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-28 00:30:29', '2026-05-02 06:24:11', NULL, NULL, NULL);
