":"3.5 mm","connectivity":"Wi-Fi 6E (802.11ax), Bluetooth 5.3","card_reader":"Không","webcam":"HD webcam","operating_system":"Windows 11 Home SL + Office Home 2024 vĩnh viễn + Microsoft 365 Basic","keyboard_backlight":"Không có đèn","security":"Công tắc khoá camera","cooling_system":"Hãng không công bố","special_features":"Độ bền chuẩn quân đội MIL STD 810H, Bản lề mở 180 độ","battery":"3-cell Li-ion, 42 Wh","dimensions_weight":"Dài 359.7 mm - Rộng 232.5 mm - Dày 19.9 mm - 1.7 kg","build_material":"Vỏ nhựa","release_year":"2025"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["512GB"]},{"name":"color","values":["Bạc"]}]', 0, 0, '0.00', '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-28 00:46:54', '2026-05-02 06:24:11', NULL, NULL, NULL);
